ALTER TABLE `agent_event` MODIFY COLUMN `event_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事件类型（STATE_CHANGED/STEP_STARTED/STEP_COMPLETED/TASK_FAILED 等）';
