ALTER TABLE `agent_event` MODIFY COLUMN `created_at` datetime NOT NULL COMMENT '事件发生时间';

ALTER TABLE `agent_invocation_log` COMMENT = '智能体调用日志表：每次 LLM 会话一条，成功/拦截/失败全记录，供观测看板聚合';
