ALTER TABLE `agent_invocation_log` MODIFY COLUMN `latency_ms` bigint DEFAULT NULL COMMENT '端到端耗时（毫秒）';
ALTER TABLE `agent_invocation_log` MODIFY COLUMN `input_tokens` bigint DEFAULT NULL COMMENT '本次会话累计输入 token（估算值）';
